int oldfd = 3;
int newfd = 10;
int result;

// O_CLOEXEC ensures newfd is closed on execve()
int flags = O_CLOEXEC; 

// Fails if oldfd == newfd or invalid flags
result = dup3(oldfd, newfd, flags);

if (result == -1) {
    // EBADF: oldfd invalid or newfd out of range
    // EINVAL: oldfd == newfd or invalid flags
}
